INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运二年八月奏马希杲卒", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-084-945-august/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年八月奏马希杲卒，段落 jiu-wudaishi-205deb4a7860-p002028；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "d771a89b-2508-55c3-a20a-5b5c55c4b3b0"}, {"title": "旧五代史·卷84·晋少帝本纪·开运二年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-084-945-june/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年六月，段落 jiu-wudaishi-205deb4a7860-p002026；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "58e20d6d-7089-523c-8926-c75d534e016f"}, {"title": "旧五代史·卷84·晋少帝本纪·开运二年五月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-084-945-may/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年五月，段落 jiu-wudaishi-205deb4a7860-p002025；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "a7772071-1170-5ab4-bc50-ce34544772f5"}, {"title": "旧五代史·卷109·杜重威传·擅离恒州及此后事", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-109-du-leaves/source.txt", "note": "《旧五代史》卷109·杜重威传·擅离恒州及此后事，段落 jiu-wudaishi-205deb4a7860-p002617；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "186cc6db-af14-5154-813a-ddcc1501d60e"}, {"title": "旧五代史·卷109·杜重威传·家世与恒州任职", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-109-du-wife/source.txt", "note": "《旧五代史》卷109·杜重威传·家世与恒州任职，段落 jiu-wudaishi-205deb4a7860-p002616；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "f9349e26-5e2f-5c7c-842e-180f08f4a08e"}, {"title": "资治通鉴·卷284·后晋纪五·开运二年七月末两段", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/tongjian-284-945-july-ending/source.txt", "note": "《资治通鉴》卷284·后晋纪五·开运二年七月末两段，段落 zizhi-tongjian-a63549944a71-p003382；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "d50da7b7-6d47-5e23-b30f-908d7d396f08"}, {"title": "资治通鉴·卷284·后晋纪五·开运二年五月至七月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/tongjian-284-945-may-july/source.txt", "note": "《资治通鉴》卷284·后晋纪五·开运二年五月至七月及追述，段落 zizhi-tongjian-a63549944a71-p003381；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"title": "新五代史·卷29·景延广传·晋向契丹求和", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/xinwudaishi-029-jing-peace/source.txt", "note": "《新五代史》卷29·景延广传·晋向契丹求和，段落 xin-wudaishi-b08f244b9241-p001070；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "827ab168-f367-500c-bd46-fe7815af2f1b"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "新五代史·卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理）", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/xinwudaishi-068-li-ren-da/source.txt", "note": "《新五代史》卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理），段落 xin-wudaishi-b08f244b9241-p003414；上下文、卷界及传主已校核，纸本及异文待核。", "id": "4c007e7d-1965-54c8-99ae-fa57eab6e1a4"}]'::jsonb)
