SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "石重贵在五月初一宣布大赦。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p025·原文件第76行", "note": "原文：五月，丙申朔，大赦。；核对说明：五月大赦与此前四月还京赦京城囚犯是两次处置。", "status": "draft", "id": "6b12ba27-63d9-5b50-8422-ca84f5286ed9", "subject_id": "5bcd76d5-ec28-585d-accc-173f55aa4add", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "945年五月丙申朔", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p025·原文件第76行", "note": "原文：五月，丙申朔，大赦。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "4a2f4f29-275b-59d2-a16b-71cbce7cffb7", "subject_id": "5bcd76d5-ec28-585d-accc-173f55aa4add", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person", "field_path": "description", "claim_text": "石重贵：宣布大赦。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p025·原文件第76行", "note": "原文：五月，丙申朔，大赦。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "e7fc0d2b-8e90-5999-bff6-ce4d17b125f5", "subject_id": "2741e60a-9bf9-56a7-b30d-3db439caa139", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石重贵：宣布大赦。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p025·原文件第76行", "note": "原文：五月，丙申朔，大赦。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6c44c871-1e83-58a7-bcfe-0f3fbacd3cdf", "subject_id": "488c9c15-6f8f-547b-8fa8-8e280e6b944c", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》明确石重贵在崇元殿受朝后大赦天下。", "citation": "《旧五代史》卷84·晋少帝本纪·开运二年五月，段落 jiu-wudaishi-205deb4a7860-p002025；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "note": "原文：開運二年夏五月丙申朔，帝御崇元殿受朝，大赦天下。；核对说明：同日同次大赦，补殿名与受朝，不并入此前四月赦囚。", "status": "draft", "id": "c36b477c-68d0-585b-ab4d-34951f29261a", "subject_id": "5bcd76d5-ec28-585d-accc-173f55aa4add", "source_id": "a7772071-1170-5ab4-bc50-ce34544772f5"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》同记五月丙申朔大赦。", "citation": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "note": "原文：五月丙申朔，大赦。；核对说明：同日同事，保留独立书证。", "status": "draft", "id": "959c4a25-a4a2-5bce-a7a3-3ed5415dcdf9", "subject_id": "5bcd76d5-ec28-585d-accc-173f55aa4add", "source_id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"subject_table": "event", "field_path": "description", "claim_text": "杜重威长期以备边为名征敛钱帛，收入私库。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：顺国节度使杜威，久镇恒州，性贪残，自恃贵戚，多不法。每以备边为名，敛吏民钱帛以充私藏。；核对说明：久镇与每以描述长期作为，不把全部征敛强定五月单日；贪残是史书记载的评价。", "status": "draft", "id": "966d01dc-3ccf-5910-9eb6-00ca3b2a33ac", "subject_id": "0519e04f-ba0c-5b43-bf9a-ee5a1fad1ecb", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "杜重威长期镇守恒州期间，具体起止年未载", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：顺国节度使杜威，久镇恒州，性贪残，自恃贵戚，多不法。每以备边为名，敛吏民钱帛以充私藏。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "489ac345-52de-564b-9606-30bc380d209c", "subject_id": "0519e04f-ba0c-5b43-bf9a-ee5a1fad1ecb", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person", "field_path": "description", "claim_text": "杜重威：以边防为名向官吏和百姓敛取钱帛，收入私库。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：顺国节度使杜威，久镇恒州，性贪残，自恃贵戚，多不法。每以备边为名，敛吏民钱帛以充私藏。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "fa22f05b-9f6a-538b-8745-47913142808d", "subject_id": "e5e23c10-447f-5238-bc56-f376300f9bac", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜重威：以边防为名向官吏和百姓敛取钱帛，收入私库。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：顺国节度使杜威，久镇恒州，性贪残，自恃贵戚，多不法。每以备边为名，敛吏民钱帛以充私藏。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "10832ff9-6070-52fd-8b47-49f3a04d3815", "subject_id": "edd1033c-6623-50a2-aa98-93b024204b09", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记杜重威到镇后在税外加征，境内百姓深受其苦。", "citation": "《旧五代史》卷109·杜重威传·家世与恒州任职，段落 jiu-wudaishi-205deb4a7860-p002616；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "note": "原文：至鎮，復重斂於民，稅外加賦，境內苦之；核对说明：传记先叙安重荣败后任镇，说明这是长期征敛，不另造945年新一次征税。", "status": "draft", "id": "e548a5e7-ed93-577c-8015-a5fcc709555e", "subject_id": "0519e04f-ba0c-5b43-bf9a-ee5a1fad1ecb", "source_id": "f9349e26-5e2f-5c7c-842e-180f08f4a08e"}, {"subject_table": "event", "field_path": "description", "claim_text": "杜重威强取富户珍货、女子与骏马，有时诬罪杀人并没收家产。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：富室有珍货或名姝、骏马，皆虏取之；或诬以罪杀之，籍没其家。；核对说明：或诬为部分事例，未具名受害者不建立占位人物；名姝指被强取女子，不改写成自愿婚配。", "status": "draft", "id": "d8fd6cc6-be53-5c92-90d0-59417849aefb", "subject_id": "9acc14f3-3650-5a2f-8461-2e674fe31e1f", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "杜重威镇守恒州期间的反复行为，具体年月未载", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：富室有珍货或名姝、骏马，皆虏取之；或诬以罪杀之，籍没其家。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "cab198fc-66a9-578f-b74c-74e334e93255", "subject_id": "9acc14f3-3650-5a2f-8461-2e674fe31e1f", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜重威：强取富户财物、女子和马匹，有时诬罪杀人并没收其家产。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：富室有珍货或名姝、骏马，皆虏取之；或诬以罪杀之，籍没其家。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "cc9fc073-c29b-54fe-9aee-ee84b39ec939", "subject_id": "4a265de4-fe95-5bbb-8800-3a8d32656dcb", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "description", "claim_text": "杜重威见契丹骑兵入境便闭城，未拦救被掳百姓。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：又畏懦过甚，每契丹数十骑入境，威已闭门登陴；或数骑驱所掠华人千百过城下，威但真目延颈望之，无意邀取。；核对说明：电子本目字前有私用字，原文保留；行为按前后文写出，不凭乱码恢复字形。人数千百为史书概述，不推单次准确统计。", "status": "draft", "id": "59b0aa99-7a10-5e1a-98f4-1c0225d20a29", "subject_id": "8ec60949-bba3-523f-9505-6e01e8741f2b", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "契丹连年攻晋、杜重威镇恒州期间，具体年月未载", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：又畏懦过甚，每契丹数十骑入境，威已闭门登陴；或数骑驱所掠华人千百过城下，威但真目延颈望之，无意邀取。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "2c55906e-4dd8-5824-860d-edc6d14c6786", "subject_id": "8ec60949-bba3-523f-9505-6e01e8741f2b", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜重威：在契丹骑兵入境时闭城，未出兵拦救被掳百姓。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：又畏懦过甚，每契丹数十骑入境，威已闭门登陴；或数骑驱所掠华人千百过城下，威但真目延颈望之，无意邀取。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "ac0e2f3d-a14f-54bc-a0b9-83ccff4af21e", "subject_id": "e32e77c5-78af-57a7-a127-e43058cde520", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记杜重威在城上旁观，未出兵拦救；该书被掳人数写千萬。", "citation": "《旧五代史》卷109·杜重威传·擅离恒州及此后事，段落 jiu-wudaishi-205deb4a7860-p002617；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "note": "原文：每敵騎數十驅漢人千萬過城下，如入無人之境，重威但登陴註目，略無邀取之意。；核对说明：《资治通鉴》千百与《旧五代史》千萬不同，保留底本文字，不据此计算精确人口损失。", "status": "draft", "id": "971fb0fa-9400-5d7c-bd27-57ca26940a6d", "subject_id": "8ec60949-bba3-523f-9505-6e01e8741f2b", "source_id": "186cc6db-af14-5154-813a-ddcc1501d60e"}, {"subject_table": "event", "field_path": "description", "claim_text": "契丹军破坏恒州所辖城邑，杜重威未出兵救援。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：由是虏无所忌惮，属城多为所屠，威竟不出一卒救之，千里之间，暴骨如莽，村落殆尽。；核对说明：千里与村落殆尽为史书对毁坏的概述，不换算地理半径或精确村数。", "status": "draft", "id": "4a1f07cd-6d07-5f84-9cf0-5a7acb14e686", "subject_id": "ae06fdc7-5b85-502f-8066-d495f8226321", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "杜重威镇恒州、契丹连年攻晋期间，具体起止年月未载", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：由是虏无所忌惮，属城多为所屠，威竟不出一卒救之，千里之间，暴骨如莽，村落殆尽。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b3af8cca-a966-5c1b-9810-f90f9f4134cd", "subject_id": "ae06fdc7-5b85-502f-8066-d495f8226321", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜重威：面对所辖城邑遭屠掠，未派兵救援。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：由是虏无所忌惮，属城多为所屠，威竟不出一卒救之，千里之间，暴骨如莽，村落殆尽。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "5a644d10-910f-5593-96b1-675730a66e65", "subject_id": "89a23ca2-5907-5a9c-816d-fed9f95fa6e9", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记恒州辖境城邑相继失陷，杜重威未派兵救援。", "citation": "《旧五代史》卷109·杜重威传·擅离恒州及此后事，段落 jiu-wudaishi-205deb4a7860-p002617；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "note": "原文：部內城邑相繼破陷，一境生靈受屠戮，重威任居方面，未嘗以一土一騎救之。；核对说明：原文一土一骑疑有字形问题，逐字保留；不靠自动转换校订纸本。", "status": "draft", "id": "b92914b2-3f65-527f-ba72-d2f830749a9a", "subject_id": "ae06fdc7-5b85-502f-8066-d495f8226321", "source_id": "186cc6db-af14-5154-813a-ddcc1501d60e"}, {"subject_table": "event", "field_path": "description", "claim_text": "杜重威多次请求入朝，石重贵不批准。", "citation": "卷284·后晋开运二年（945年五月至七月及追述）·zztj-v284-y0945-p026·原文件第77行", "note": "原文：威见所部残弊，为众所怨，又畏契丹之强，累表请入朝，帝不许；；核对说明：请求动机来自史书叙述，不推成已准备投敌。", "status": "draft", "id": "5ff3b6d8-85ad-58c5-9351-f5e9cd12a18e", "subject_id": "b832b1b8-e437-53af-9538-6e2180c0c6d1", "source_id": "43402fc1-94a7-503e-a388-8dc62af40a80"}, {"su